function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function publicHtml(pathname="/"){const pages={"/privacy":["Privacy Policy | MixoLabs","Read the MixoLabs privacy policy and learn how personal information is handled."],"/terms":["Terms and Conditions | MixoLabs","Read the terms and conditions for using the MixoLabs AI image generator."],"/support":["Support | MixoLabs","Get help with MixoLabs image generation, accounts, credits and billing."],"/faq":["Frequently Asked Questions | MixoLabs","Answers to common questions about MixoLabs images, credits, accounts and safety."]},clean=pathname!=="/"?pathname.replace(/\/$/,""):"/",meta=pages[clean]||["MixoLabs — AI Image Generator","Create original AI-generated images for creative projects with MixoLabs."],canonical=`https://mixolabs.art${clean}`;return fs.readFileSync(path.join(__dirname,"index.html"),"utf8").replace("<title>MixoLabs — AI Image Generator</title>",`<title>${escapeHtml(meta[0])}</title>`).replaceAll("{{PAGE_TITLE}}",escapeHtml(meta[0])).replaceAll("{{PAGE_DESCRIPTION}}",escapeHtml(meta[1])).replaceAll("{{CANONICAL_URL}}",escapeHtml(canonical)).replaceAll("{{LEGAL_NAME}}",escapeHtml(PUBLIC_LEGAL_NAME)).replaceAll("{{LEGAL_ADDRESS}}",escapeHtml(PUBLIC_LEGAL_ADDRESS)).replaceAll("{{SUPPORT_EMAIL}}",escapeHtml(PUBLIC_SUPPORT_EMAIL)).replace("</body>",'<script src="/random-infinite.js"></script></body>')}
app.get("/",(req,res)=>res.type("html").send(publicHtml(req.path)));app.get("*",(req,res)=>res.type("html").send(publicHtml(req.path)));
app.use((e,req,res,next)=>{console.error("request_failed",{path:req.path,message:e.message});if(res.headersSent)return next(e);res.status(e.status||500).json({error:e.status?e.message:"Something went wrong. Please try again."})});
migrate().then(()=>server.listen(PORT,()=>console.log(`MixoLabs running on port ${PORT}`))).catch(e=>{console.error("startup_failed",e);process.exit(1)});
